import math
import itertools

results = []

# Iterate over all triples (a, b, c) such that 1 <= a <= b <= c <= 10
for a in range(1, 11):
    for b in range(a, 11):
        for c in range(b, 11):
            # Calculate E = sqrt(1001/a) + sqrt(1001/b) + sqrt(1001/c)
            try:
                term_a = math.sqrt(1001 / a)
                term_b = math.sqrt(1001 / b)
                term_c = math.sqrt(1001 / c)
                E = term_a + term_b + term_c

                # Check if E is an integer. Since we are using floats, we check if it's close to an integer.
                # We check if abs(E - round(E)) is very small.
                is_integer = abs(E - round(E)) < 1e-9

                if is_integer:
                    results.append((a, b, c, E))
            except ValueError:
                # Should not happen as a, b, c are positive
                pass

print("--- Found Solutions ---")
if results:
    for a, b, c, E in results:
        print(f"Triple ({a}, {b}, {c}): E = {E}, which is an integer.")
else:
    print("No solutions found in the range 1 <= a <= b <= c <= 10.")

